def document(title,description,content,prefix='',active='',article=False):
    title=escape(title)
    description=escape(description,quote=True)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="{description}"><meta property="og:title" content="{title} | The Imāmī Review"><meta property="og:description" content="{description}"><meta property="og:type" content="{'article' if article else 'website'}"><title>{title} | The Imāmī Review</title><link rel="icon" type="image/svg+xml" href="{prefix}assets/favicon.svg"><link rel="stylesheet" href="{prefix}assets/styles.css"><script src="{prefix}assets/site.js" defer></script></head><body>{'<div class="reading-progress" aria-hidden="true"></div>' if article else ''}{nav(prefix,active)}<main id="main">{content}</main>{footer(prefix)}</body></html>'''

def card(a,i,prefix=''):
    return f'''<a class="article-card" data-article data-category="{a['category']}" href="{prefix}articles/{a['slug']}.html"><div class="card-art card-art--{(i%3)+1}"><span class="arabesque" lang="ar" aria-hidden="true">{a['art']}</span></div><div class="card-content"><span class="category">{escape(a['category_name'])}</span><h3>{escape(a['title'])}</h3><p>{escape(a['subtitle'])}</p><div class="card-bottom"><span>{a['minutes']} min read · Editorial draft</span><span aria-hidden="true">↗</span></div></div></a>'''

